function paintSpiderFusion(s,frame){
 const runs=SPIDER_FRAMES[frame];if(!runs)throw new RangeError('Unknown spider frame '+frame);let pixel=0;
 for(let i=0;i<runs.length;i+=2){const n=runs[i],color=runs[i+1];if(color)for(let k=0;k<n;k++){const p=pixel+k;s.set(p%SPIDER_SHEET.W,Math.floor(p/SPIDER_SHEET.W),SPIDER_COLORS[color]);}pixel+=n;}
}
